"""Lockfile parsing and exact-version CVE queries.

Fixtures are trimmed copies of real lockfiles (generated by npm/pnpm/yarn/uv
or taken from public repos) so format quirks are covered.
"""
import io
import os
import sys
import tempfile
import unittest
from contextlib import redirect_stderr
from unittest import mock

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

