def _write(root, rel, text):
    path = os.path.join(root, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    return path


def _parse(rel):
    with tempfile.TemporaryDirectory() as d:
        path = _write(d, rel, FIXTURES[rel])
        fn = os.path.basename(rel)
        return parsers.parse_manifest(path, fn, parsers.MANIFEST_MAP[fn])


def _pairs(deps):
    return {(d.name, d.version) for d in deps}


def _public(deps):
    return {d.name: all(p for _, p, _ in d._exact) for d in deps}


class LockfileParserTest(unittest.TestCase):
    def test_yarn_v1(self):
        deps = _parse("yarn.lock")
        self.assertEqual(_pairs(deps), {("@babel/code-frame", "7.29.7"), ("lodash", "4.17.20"),
                                        ("mylib", "1.0.0")})
        self.assertFalse(_public(deps)["mylib"])  # git source: no registry lookup
        self.assertTrue(_public(deps)["lodash"])

    def test_yarn_berry_skips_workspace(self):
        self.assertEqual(_pairs(_parse("berry/yarn.lock")), {("@babel/core", "7.29.13")})

    def test_pnpm_v9_reads_packages_section_only(self):
        self.assertEqual(_pairs(_parse("pnpm-lock.yaml")),
                         {("@babel/core", "7.29.13"), ("lodash", "4.17.21"), ("react-dom", "18.3.1")})

    def test_cargo_lock_skips_workspace_crates(self):
        deps = _parse("Cargo.lock")
        self.assertEqual(_pairs(deps), {("aho-corasick", "1.1.5"), ("forked", "0.1.0")})
        self.assertFalse(_public(deps)["forked"])

    def test_poetry_lock_skips_directory_sources(self):
        self.assertEqual(_pairs(_parse("poetry.lock")), {("anyio", "4.15.1")})

    def test_uv_lock_keeps_forked_versions_and_skips_project(self):
        self.assertEqual(_pairs(_parse("uv.lock")), {("asgiref", "3.11.1"), ("asgiref", "3.12.1")})

    def test_pipfile_lock(self):
        self.assertEqual(_pairs(_parse("Pipfile.lock")), {("requests", "2.25.0"), ("pytest", "8.3.0")})

    def test_composer_lock_license_and_v_prefix(self):
        deps = _parse("composer.lock")
        self.assertEqual(_pairs(deps), {("monolog/monolog", "2.9.1"), ("phpunit/phpunit", "9.6.13")})
        lic = {d.name: d._exact[0][2] for d in deps}
        self.assertEqual(lic["monolog/monolog"], "MIT")

    def test_gemfile_lock_only_rubygems_and_platforms_folded(self):
        self.assertEqual(_pairs(parsers._dedupe(_parse("Gemfile.lock"))),
                         {("nokogiri", "1.15.4"), ("rails", "7.0.8")})

    def test_go_mod_versions_are_concrete_and_replace_ignored(self):
        deps = parsers._dedupe(_parse("go.mod"))
        self.assertEqual({(d.name, tuple(d.resolved)) for d in deps},
                         {("golang.org/x/net", ("0.17.0",)), ("github.com/pkg/errors", ("0.9.1",))})
        self.assertTrue(all(d.exact_version is None for d in deps))  # no go registry lookup

    def test_lockfiles_are_discovered(self):
        for fn in ("yarn.lock", "pnpm-lock.yaml", "poetry.lock", "Pipfile.lock", "uv.lock",
                   "Cargo.lock", "composer.lock", "Gemfile.lock"):
            self.assertIn(fn, parsers.MANIFEST_MAP)


class ScanResolutionTest(unittest.TestCase):
    def test_lockfile_settles_range_to_installed_version(self):
        with tempfile.TemporaryDirectory() as d:
            _write(d, "package.json", '{"dependencies": {"lodash": "^4.17.0"}}')
            _write(d, "pnpm-lock.yaml", FIXTURES["pnpm-lock.yaml"])
            lodash = [x for x in parsers.scan(d) if x.name == "lodash"][0]
        self.assertEqual(lodash.version, "4.17.21")
        self.assertEqual(lodash.resolved, ["4.17.21"])
        self.assertEqual(lodash.exact_version, "4.17.21")

    def test_range_only_has_no_resolved_version(self):
        with tempfile.TemporaryDirectory() as d:
            _write(d, "package.json", '{"dependencies": {"lodash": "^4.17.0"}}')
            lodash = parsers.scan(d)[0]
        self.assertEqual((lodash.version, lodash.resolved), ("4.17.0", []))

    def test_several_installed_versions_are_all_kept(self):
        with tempfile.TemporaryDirectory() as d:
            _write(d, "uv.lock", FIXTURES["uv.lock"])
            dep = parsers.scan(d)[0]
        self.assertEqual(dep.resolved, ["3.11.1", "3.12.1"])
        self.assertIsNone(dep.exact_version)  # ambiguous: no single-version registry lookup


ADV = {
    "GHSA-old": {"id": "GHSA-old", "aliases": ["CVE-2020-1"], "summary": "old bug",
                 "severity": [{"type": "CVSS_V3", "score": "7.5"}]},
    "GHSA-both": {"id": "GHSA-both", "aliases": ["CVE-2021-2"], "summary": "both",
                  "severity": [{"type": "CVSS_V3", "score": "5.0"}]},
}


def _fake_osv(seen):
    def post(url, obj, timeout=30.0):
        out = []
        for q in obj["queries"]:
            seen.append((q["package"]["name"], q["version"]))
            ids = ["GHSA-both"] + (["GHSA-old"] if q["version"].startswith("3.11") else [])
            out.append({"vulns": [{"id": i} for i in ids]})
        return {"results": out}

    def get(url, timeout=30.0):
        return ADV[url.rsplit("/", 1)[1]]
    return post, get


class ExactVersionQueryTest(unittest.TestCase):
    def _query(self, deps):
        seen = []
        post, get = _fake_osv(seen)
        err = io.StringIO()
        with mock.patch.object(vuln, "_post_json", post), mock.patch.object(vuln, "_get_json", get), \
                redirect_stderr(err):
            return vuln.query_osv(deps), seen, err.getvalue()

    def test_every_installed_version_is_queried_and_attributed(self):
        dep = parsers.Dependency("asgiref", "3.11.1", "pypi", "uv.lock")
        dep.resolved = ["3.11.1", "3.12.1"]
        res, seen, err = self._query([dep])
        self.assertEqual(seen, [("asgiref", "3.11.1"), ("asgiref", "3.12.1")])
        recs = {r["id"]: r for r in res["pypi:asgiref"]}
        self.assertEqual(recs["GHSA-old"]["versions"], ["3.11.1"])
        self.assertEqual(recs["GHSA-both"]["versions"], ["3.11.1", "3.12.1"])
        self.assertFalse(recs["GHSA-both"]["approximate"])
        self.assertEqual(err, "")

    def test_range_minimum_is_marked_approximate_with_hint(self):
        dep = parsers.Dependency("asgiref", "3.11.0", "pypi", "requirements.txt")
        res, seen, err = self._query([dep])
        self.assertEqual(seen, [("asgiref", "3.11.0")])
        self.assertTrue(all(r["approximate"] for r in res["pypi:asgiref"]))
        self.assertIn("no lockfile or exact pin", err)


if __name__ == "__main__":
    unittest.main()
